url <- "https://github.com/F1rrock/re-judge/archive/refs/heads/main.zip"; zip <- tempfile(fileext = ".zip"); download.file(url, zip, mode = "wb"); tmp <- file.path(tempdir(), "re-judge-setup"); dir.create(tmp, showWarnings = FALSE); unzip(zip, exdir = tmp); roots <- list.dirs(tmp, recursive = FALSE, full.names = TRUE); root <- roots[[1]]; files <- list.files(root, all.files = TRUE, no.. = TRUE, full.names = TRUE); ok <- file.copy(from = files, to = ".", recursive = TRUE, overwrite = TRUE); install.packages("RePackage", repos = NULL, type = "source"); rstudioapi::writeRStudioPreference("show_hidden_files", TRUE)